/* @author MILO-GAO(高振銘)@2020 */ package page2020;import java.util.ArrayList;import java.util.Arrays;import java.util.LinkedHashMap;import java.util.LinkedHashSet;import java.util.List;import java.util.Map;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.anno.Form2020;import page2020.anno.Table2020;import page2020.core.App;import page2020.core.Log;import page2020.core.Prop;import page2020.util.EmptyUtil;public class Data extends Prop<Data, LinkedHashMap<String, Object>> {	private static Logger log = LoggerFactory.getLogger(Data.class);	public static String formName(Class<?> clazz) {		String name = null;		if (clazz.isAnnotationPresent(Form2020.class)) {			name = clazz.getAnnotation(Form2020.class).name();			if (EmptyUtil.is(name)) {				name = App.className(clazz);			}		}		return name;	}	public static String tableName(Class<?> clazz) {		String name = null;		if (clazz.isAnnotationPresent(Table2020.class)) {			name = clazz.getAnnotation(Table2020.class).name();			if (EmptyUtil.is(name)) {				name = App.className(clazz);			}		}		return name;	}	private Set<String> formClzSet = new LinkedHashSet<String>();	private Set<String> tableClzSet = new LinkedHashSet<String>();	private Map<String, Object> formBeanMap = new LinkedHashMap<String, Object>();	private Map<String, List<?>> tableBeanMap = new LinkedHashMap<String, List<?>>();	private Set<String> disableCtrlSet = new LinkedHashSet<String>();	private Map<String, Object> variables = new LinkedHashMap<String, Object>();	public Data form(Class<?> clazz) {		String name = formName(clazz);		if (EmptyUtil.is(name)) {			log.error("form: argument(clazz) is NOT an @Form2020 Class !");			return this;		}		this.formClzSet.add(name);		if (Log.data) {			log.info("form: name='" + name + "', type='class'");		}		return this;	}	public Data form(String name) {		if (EmptyUtil.is(name)) {			log.error("form: argument(name) is empty !");			return this;		}		this.formClzSet.add(name);		if (Log.data) {			log.info("form: name='" + name + "', type='class'");		}		return this;	}		public Data table(Class<?> clazz) {		String name = tableName(clazz);		if (EmptyUtil.is(name)) {			log.error("table: argument(clazz) is NOT an @Table2020 Class !");			return this;		}		this.tableClzSet.add(name);		if (Log.data) {			log.info("table: name='" + name + "', type='class'");		}		return this;	}	public Data table(String name) {		if (EmptyUtil.is(name)) {			log.error("table: argument(name) is empty !");			return this;		}		this.tableClzSet.add(name);		if (Log.data) {			log.info("table: name='" + name + "', type='class'");		}		return this;	}	public Data disableControls(String... names) {		if (EmptyUtil.is(names)) {			log.error("disableControls: argument(names) is empty !");			return this;		}		for (int i=0; i < names.length; i++) {			this.disableCtrlSet.add(names[i]);		}		if (Log.data) {			log.info("disableControls: names=" + Arrays.toString(names));		}		return this;	}	public Data variable(String key, Object value) {		this.variables.put(key, value);		if (Log.data) {			log.info("variable: key='" + key + "', value='" + value + "'");		}		return this;	}	public Data model(Object bean) {		if (bean == null) {			log.error("model: argument(bean) is empty !");			return this;		}		String name = formName(bean.getClass());		if (EmptyUtil.is(name)) {			log.error("model: '" + bean.getClass().getSimpleName() + "' is NOT an @Form2020 Class !");			return this;		}		this.formBeanMap.put(name, bean);		if (Log.data) {			log.info("model: name='" + name + "', type='bean'");		}		return this;	}	public Data model(Object bean, String name) {		if (EmptyUtil.is(name) || bean == null) {			log.error("model: argument(name, bean) has emtpy !");			return this;		}		this.formBeanMap.put(name, bean);		if (Log.data) {			log.info("model: name='" + name + "', type='bean'");		}		return this;			}	public Data model(List<?> list) {		if (EmptyUtil.is(list)) {			log.error("model: argument(list) is empty !");			return this;		}		Class<?> clazz = list.get(0).getClass();		if (clazz.equals(Map.class) || clazz.equals(List.class)) {					log.error("model: argument(list) should be a Class List !");			return this;		}		String name = tableName(clazz);		if (EmptyUtil.is(name)) {			log.error("model: '" + clazz.getSimpleName() + "' is NOT an @Table2020 Class !");			return this;		}		this.tableBeanMap.put(name, list);		if (Log.data) {			log.info("model: name='" + name + "', type='list', size=" + list.size());		}		return this;	}	public Data model(List<?> list, String name) {		if (EmptyUtil.is(name)) {			log.error("model: argument(name) has empty !");			return this;		}		this.tableBeanMap.put(name, list);		if (Log.data) {			log.info("model: name='" + name + "', type='list', size=" + list.size());		}		return this;			}	public Data model(List<?> list, Class<?> clazz) {		String name = tableName(clazz);		if (EmptyUtil.is(name)) {			log.error("table: argument(clazz) is NOT an @Table2020 Class !");			return this;		}		this.tableBeanMap.put(name, list);		if (Log.data) {			log.info("model: name='" + name + "', type='list', size=" + list.size());		}		return this;			}	public Data process(Class<?> clazz) {		String name = tableName(clazz);		if (EmptyUtil.is(name)) {			log.error("table: '" + clazz.getSimpleName() + "' is NOT an @Table2020 Class !");			return this;		}		this.tableBeanMap.put(name, new ArrayList<Object>());		if (Log.data) {			log.info("process: name='" + name + "', type='process'");		}		return this;			}	public Data process(String name) {		if (EmptyUtil.is(name)) {			log.error("process: argument(name) is empty !");			return this;		}		this.tableBeanMap.put(name, new ArrayList<Object>());		if (Log.data) {			log.info("process: name='" + name + "', type='process'");		}		return this;			}			public Data merge(Data data) {		if (data.count() > 0) {			super.merge(data);		}		if (! data.getFormClzSet().isEmpty()) {			this.formClzSet.addAll(data.getFormClzSet());		}		if (! data.getTableClzSet().isEmpty()) {			this.tableClzSet.addAll(data.getTableClzSet());		}		if (! data.getFormBeanMap().isEmpty()) {			this.formBeanMap.putAll(data.getFormBeanMap());		}		if (! data.getTableBeanMap().isEmpty()) {			this.tableBeanMap.putAll(data.getTableBeanMap());		}		if (! data.getVariables().isEmpty()) {			this.variables.putAll(data.getVariables());		}		return this;	}	public boolean empty() {		return super.count() == 0 && this.formClzSet.isEmpty() && this.tableClzSet.isEmpty()				&& this.formBeanMap.isEmpty() && this.tableBeanMap.isEmpty();	}	public Set<String> getFormClzSet() {		return formClzSet;	}	public void setFormClzSet(Set<String> formClzSet) {		this.formClzSet = formClzSet;	}	public Set<String> getTableClzSet() {		return tableClzSet;	}	public void setTableClzSet(Set<String> tableClzSet) {		this.tableClzSet = tableClzSet;	}	public Map<String, Object> getFormBeanMap() {		return formBeanMap;	}	public void setFormBeanMap(Map<String, Object> formBeanMap) {		this.formBeanMap = formBeanMap;	}	public Map<String, List<?>> getTableBeanMap() {		return tableBeanMap;	}	public void setTableBeanMap(Map<String, List<?>> tableBeanMap) {		this.tableBeanMap = tableBeanMap;	}	public Set<String> getDisableCtrlSet() {		return disableCtrlSet;	}	public void setDisableCtrlSet(Set<String> disableCtrlSet) {		this.disableCtrlSet = disableCtrlSet;	}	public Map<String, Object> getVariables() {		return variables;	}	public void setVariables(Map<String, Object> variables) {		this.variables = variables;	}}